  "implementation": "def solve(case):
    import json
    payload = case['payload']
    nodes = payload['nodes']
    core = payload['core_distance']
    distances = payload['distances']
    n = len(nodes)
    # validate core keys
    for node in nodes:
        if node not in core:
            raise ValueError('missing core distance for ' + node)
    # Union-Find (DSU)
    parent = {}
    rank = {}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True
    for node in nodes:
        parent[node] = node
        rank[node] = 0
    # build edges with canonical ordering
    edges = []
    for u, v, d in distances:
        cu = core[u]
        cv = core[v]
        mr = max(cu, cv, d)
        if u > v:
            u, v = v, u
        edges.append((mr, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    selected = []
    total = 0.0
    for mr, u, v in edges:
        if union(u, v):
            selected.append([u, v, mr])
            total += mr
            if len(selected) == n - 1:
                break
    if len(selected) != n - 1:
        raise ValueError('graph is disconnected')
    return {'edges': selected, 'total_weight': total}"
}
